KB.facts = [
 // ===== Definitions =====
 {id:"F1",kind:"definition",date:"",text:"Vendor partners are the accounts SupplyNow serves and that generate revenue: Restaurant Depot, SNAP, Chefs for Hire, Greenlight, Coltrane.",ents:["rd","snap","cfh","glg","coltrane"],src:"Ledger banner",tab:"Overview"},
 {id:"F2",kind:"definition",date:"",text:"Service partners are the four operators that deliver: PA Logistics, Sigma Fleet, Logivex, D&D Delivery. Lessors who own the trucks are not service partners.",ents:["pa","sigma","logivex","dd"],src:"Ledger banner",tab:"Service partners"},
 {id:"F3",kind:"definition",date:"",text:"Fleet ownership & leases covers the six parties that own or finance SupplyNow's trucks: Quality Supply LLC, Fleet One Leasing, Penske, MH Truck Leasing, LG Chester LLC ('Gretchen'), Kirill Gorodetskov. None of them deliver anything.",ents:["qs","fleetone","penske","mh","lgc","kirill"],src:"Fleet ownership tab, block 1",tab:"Fleet ownership & leases"},
 {id:"F4",kind:"definition",date:"2026-08-23",text:"'Reserve Fleet' is not a counterparty. It is Max Snyder's term for SupplyNow's own owned and leased fleet, costed at $94,164/month on Aug 23 (driver wages $40,907, rentals and leases $22,375, vehicle insurance $14,656, gas $9,702, repairs $6,523). There is no 'Reserve Fleet' vendor to owe money to.",ents:["max","supplynow"],src:"Max Snyder to Alvin, Aug 23 (Gmail 1a035b9dd88d0f23)",tab:"Overview"},
 {id:"F5",kind:"definition",date:"",text:"'Gretchen' on Alvin's list is LG Chester LLC (truck #1008) and 'Krill' is Kirill Gorodetskov (van #1001). Two of the six names on the Sep 1 fleet-partner list are one party each.",ents:["gretchen","lgc","kirill","t1008","t1001","alvin"],src:"Airtable Fleet base; Lease Economics sheet",tab:"Overview"},
 {id:"F6",kind:"definition",date:"",text:"'Quality Supply Limited' on Alvin's list = Quality Supply LLC, Jeff Hopkins's entity: named lessee on the #1008 LG Chester lease and the Nov 2024 lessor of units #1002–#1006.",ents:["qs","hopkins","t1008","lgc"],src:"Contracts folder: Vehicle Lease to Own 2024.pdf",tab:"Fleet ownership & leases"},
 {id:"F7",kind:"definition",date:"",text:"Airtable convention: units on a lease-to-own with payments in process are recorded as 'Owned' (confirmed by Mike, Sep 7). So 'Owned' does not mean title is held. The 'Lease Asset #' field is populated only for Fleet One and Penske units.",ents:["airtable","t1001","t1007","t1008","mike"],src:"Airtable appvrC1BEfBnvf0eu / Fleet Assets",tab:"Fleet ownership & leases"},
 {id:"F8",kind:"definition",date:"",text:"PA Logistics is a flat day-rate vendor ($1,200 full day / $600 half day on Aaron's April card). The generic service-partner rule — '75/25 of 13% delivery commission' — is the model for Sigma and CFH partners and does not apply to PA. No share of SupplyNow's RD commission goes to PA.",ents:["pa","c-pa-card","andrew","aging","sigma"],src:"Mike, Sep 7; Live Order Dash partner table",tab:"Service partners"},
 {id:"F9",kind:"definition",date:"",text:"Coltrane pass-through: SupplyNow keeps 3.75% of gross Coltrane revenue from Jul 27, 2026 and passes the rest to PA on Coltrane's Net 32 cycle (§2.1, §3.1). The only late charge is $200/day, and only after SupplyNow has received the customer's funds plus 2 business days (§3.3). There is no interest clause.",ents:["coltrane","pa","c-pa-coltrane"],src:"Contracts folder: SupplyNow_x_PA_Transport_Agreement_Coltrane_v2",tab:"PA reconciliation"},
 {id:"F10",kind:"definition",date:"",text:"Restaurant Depot's contractual markup base is the in-store shelf price: delivery = ceil(shelf × 1.135), pickup = ceil(shelf × 1.05). The same gap read against the delivered price is 11.89% / 4.76% — so commission computed off an order subtotal must use 11.894% and 4.762%, not 13.5% and 5%. Applying 13.5% to an order total overstates revenue by about 13%.",ents:["rd","c-rd-2026","pricing-dash"],src:"RD storefront read Sep 9; rd_orders order_items",tab:"RD pricing tiers"},
 {id:"F11",kind:"definition",date:"",text:"Schedule 1 is the RD rate lever: SupplyNow may set its own markups and per-order fees plus customer discounts, submitted for JRD approval, set by store ID (discounts by member ID). Constraints: JRD's discretion, 1–2 weeks to enable, changes no more than once per quarter. The number filed has to hold for 90 days.",ents:["rd","c-rd-2026","pricing-dash","jaime"],src:"2026 Delivery Partner Agreement, Schedule 1",tab:"RD pricing tiers"},
 {id:"F12",kind:"definition",date:"",text:"What 'go live' means for Depot pricing: the first pricing export from the RD Pricing Dash — a Depot upload CSV at the agreed card plus lane-fee updates. It is not by itself a change at Restaurant Depot; rates change through a Schedule 1 filing JRD approves.",ents:["pricing-dash","rd","mike"],src:"Go-live review artifact 9728b5fe",tab:"Pricing go-live & labor budget"},
 {id:"F13",kind:"definition",date:"",text:"FMCSA operating authority is not transferable in an asset purchase. SupplyNow runs on USDOT 3976910 / MC 1660872 registered to SupplyNow Inc. The NewCo needs its own USDOT and MC (MCSA-1, $300 per authority, BOC-3, BMC-91X, then vetting, UCR, New Entrant audit; MC typically 3–8 weeks) or a written sub-contract through SupplyNow Inc until active.",ents:["supplynow","newco","glen","alvin","mike"],src:"Mike to Alvin and Camille, Sep 10, 8:26 PM ('Drivers' thread)",tab:"Sweep Sep 9–11"},
 {id:"F14",kind:"definition",date:"",text:"The aging tracked accrual and was blind to settlement, which is why a partner could be owed money while the report looked current. Every row on payout_history read 'Open' as of Sep 8, including Sigma weeks Camille's own tally shows as paid.",ents:["aging","camille","sigma"],src:"AP/AR check-off thread, Sep 8",tab:"Balances & AP/AR"},
 {id:"F15",kind:"definition",date:"",text:"Justworks runs in two phases: quoting/underwriting (company and workforce data, workers' comp class, benefits, state footprint → firm quote) then implementation/onboarding (employee onboarding, tax and state setup, cutover from Deel). Next onboarding window is Nov 6, 2026.",ents:["justworks","deel","glen","mike"],src:"Mike's dictated notes, Sep 11; 'Just Works Discovery & Intake Review' doc",tab:"Payroll / PEO"},
 {id:"F16",kind:"definition",date:"",text:"The custom software: React admin at admin.supplynow.org (Vercel) → Django REST API at api.supplynow.io (Railway, 326 endpoints) → driver and shopper apps. Modules: orders and depot ingestion, shopper picking, driver routes (Routific), chat, load board, payouts, invoices, receipts, fleet PDF extraction, Twilio SMS login, Stripe, S3. AIT is the outside dev shop.",ents:["portal","ait","aaron"],src:"admin.supplynow.org and api.supplynow.io, inspected Sep 14",tab:"Sweep Sep 12–14"},
 {id:"F17",kind:"definition",date:"",text:"Pickup mix, not delivery price, decides each depot's take: pickup earns 5% and no fee, delivery earns 13.5% plus $50. Wilkes-Barre (20.6% pickup) earns 15.76%; Akron (66.3% pickup) earns 9.88%. For the five depots above 50% pickup, the pickup rate and a pickup fee are the only workable levers — and there is no pickup fee today.",ents:["rd","m-wb","m-akron","m-columbus","m-indy","m-michigan","pricing-dash"],src:"rd_orders, Jul 5 – Sep 7, 2026 (2,048 orders)",tab:"RD pricing tiers"},
 // ===== SNAP =====
 {id:"F20",kind:"moment",date:"2024-10-31",text:"SNAP Strategic Alliance Agreement signed (DocuSign 639C565A): Aaron George 10/31/2024, Jason Chamoun. Schedule 1 Project Plan effective Nov 4, 2024, in effect until Nov 5, 2025. No Schedule 1 dated after that is on file.",ents:["snap","c-snap-msa","aaron","jason"],src:"Drive: Final SNAP X Docusign (1).pdf",tab:"Vendor partners"},
 {id:"F21",kind:"finding",date:"2026-09-07",text:"SNAP's 3% annual escalator ($86 → $88.58/hr due Nov 11, 2025) was never applied. Unbilled Nov 11, 2025 – Sep 4, 2026: 3,341.5 hours, $8,624.37. Run-rate about $265/week if the rate stays at $86. Second escalator falls due Nov 11, 2026 ($91.24/hr). Airtable still bills at $86.",ents:["snap","c-snap-msa","airtable"],src:"Jul 10 contract-review notes; Airtable SNAP billing",tab:"Vendor partners"},
 {id:"F22",kind:"number",date:"2026-09-10",text:"SNAP receivable: $30,286.88 open — invoice 006 $8,648.94 (due 8/31), 007 $11,332.58 (due 9/7), 008 $10,305.36 (due 9/14). 2026 wires from SNAP Jan 5 – Aug 31: $244,468 across 35 weeks. SNAP states net terms are 14 days, not 7.",ents:["snap","amanda"],src:"Airtable SNAP billing; Mercury",tab:"Balances & AP/AR"},
 {id:"F23",kind:"finding",date:"",text:"SNAP assignment §12(m): consent 'not required for an assignment in connection with a change of control, merger, or sale of substantially all the assets.' The cleanest contract to transfer to the NewCo.",ents:["snap","c-snap-msa","newco"],src:"SNAP MSA §12(m)",tab:"Vendor partners"},
 {id:"F24",kind:"open",date:"",text:"SNAP open items: new Schedule 1 (none after Nov 5, 2025); the $8,624 escalator catch-up invoice; no written record that the $649/week truck deduction was ended; fuel surcharge rate confusion ($1.39 in contract vs $1.83/$1.89 in Airtable).",ents:["snap","c-snap-msa","camille","mike"],src:"Vendor partners tab",tab:"Vendor partners"},
 // ===== Restaurant Depot =====
 {id:"F30",kind:"moment",date:"2025-01-29",text:"RD Delivery Partner Contract executed: Aaron George 1/25/2025, Jaime Kriss (SVP) 1/29/2025. DocuSign 01E689F3. At least 13% delivery / 5% pickup; 'not transferable without the written approval of JRD.'",ents:["rd","c-rd-2025","aaron","jaime"],src:"Drive 1xlEhHL1EKNvwIAP1NVW_uAXOv8TjbM50",tab:"Vendor partners"},
 {id:"F31",kind:"moment",date:"2026-06-08",text:"RD 2026 Delivery Partner Agreement: Aaron signed 6/8/2026 (DocuSign 597B47FA). JRD's signature block (Jaime Kriss) is blank on the copy; no certificate of completion. Adds 45-day convenience termination for either side; keeps the anti-transfer sentence; default markups 13.5% / 5%.",ents:["rd","c-rd-2026","aaron","jaime"],src:"Contracts folder: Delivery partner contract - 2026 RDepot",tab:"Documents read"},
 {id:"F32",kind:"moment",date:"2026-08-28",text:"Quarterly Depot Call (Aaron, Mike, Alvin, Jaime): 36.3% quarterly growth; fill rate 93%; Dayton territory approved pending Jaime's confirmation; 'A new contract will be executed to accommodate changes to the company entity and insurance provider.' Jaime asked to be notified of entity or insurance changes. No notice sent on record.",ents:["rd","jaime","aaron","mike","alvin","m-dayton"],src:"Aug 28 Depot call notes",tab:"Vendor partners"},
 {id:"F33",kind:"finding",date:"2026-09-09",text:"Measured live Sep 9 at all six company depots: every delivery/pickup price pair matched ceil(shelf × 1.135) and ceil(shelf × 1.05), zero exceptions (88 delivery pairs, mean 13.55%). SupplyNow has never exercised its Schedule 1 right — the stores run JRD's factory setting.",ents:["rd","pricing-dash","m-cleveland","m-akron","m-pittsburgh","m-wb","m-indy","m-columbus"],src:"RD member storefront, Sep 9, 2026",tab:"RD pricing tiers"},
 {id:"F34",kind:"number",date:"2026-09-07",text:"RD volume, 9 weeks Jul 5 – Sep 7: 2,048 orders across nine stores, $2,021,361 shelf value, $250,977 SupplyNow revenue, 12.42% blended take, $123 per order. Monthly run-rate $120,831 (OH/PA six stores $102,481; Michigan $18,351).",ents:["rd","m-wb","m-cleveland","m-pittsburgh","m-columbus","m-akron","m-michigan","m-indy"],src:"rd_orders warehouse",tab:"RD pricing tiers"},
 {id:"F35",kind:"number",date:"2026-09-08",text:"RD receivable snapshot (Camille, Sep 8): Aug 9–15 billed $27,524.55 unpaid; Aug 16–22 $52,913.21 ($41,854.17 received Aug 28); Aug 23–29 $25,619.01 received Sep 4. Open about $38,584. Weekly RD commission Jul–Aug ran $22.9K–$28.6K.",ents:["rd","camille"],src:"Camille's RD receipt tab",tab:"Sales & P&L"},
 {id:"F36",kind:"finding",date:"2026-09-10",text:"Candidate rate cards priced on the real 2,048 orders (per month): Current 13.5%/5%·$50/$0 = $120,831 (12.42%); Max's flat 20%/7.5%·$30 = $157,036 (16.14%); Balanced 16%/9%·$50/$25 = $163,463 (16.80%); Pickup-led 15%/10%·$50/$35 = $166,969 (17.16%); Aggressive 18%/10%·$60/$35 = $188,561 (19.38%). Break-even on Mike's cost stack is under an 18% blended take.",ents:["rd","pricing-dash","max","mike"],src:"RD pricing tiers tab, block 4",tab:"RD pricing tiers"},
 {id:"F37",kind:"number",date:"2026-09-12",text:"Working card on the dash (18% delivery, 8.5% pickup, $39.99 delivery fee, velocity on): blended take 15.79%, about $151,003/month, +$33,949/month — 202% of the $16,844 hole to the 14% floor. Eighteen delivery lanes still lose money on every drop ($50,445 across 73 deliveries); lever ⑤ (lane fee by distance) fixes those.",ents:["pricing-dash","rd","mike"],src:"RD Pricing Dash, Sep 10–12",tab:"Pricing go-live & labor budget"},
 {id:"F38",kind:"open",date:"2026-09-14",text:"Depot pricing go-live: target Thu Sep 17 (two other dates in circulation: 'Fri Sep 18' and 'Thu Sep 18'). Eleven pending asks — lock the card (four candidates), who files Schedule 1 while Aaron is on PTO, categorization pass (1,074 Unclassified), unit/case mismatches (54–70), needs-review bucket (597 items), RD's importer template, cost-to-serve constants (Glen), rotate the Anthropic API key, ops ownership of depot@ and RED alerts, OSRM/backup, dev tailnet access.",ents:["pricing-dash","mike","matt","aaron","alvin","glen","rd"],src:"Go-live review, Sep 14",tab:"Pricing go-live & labor budget"},
 {id:"F39",kind:"decision",date:"2026-09-10",text:"Strategic-plan workstreams (Alvin, Sep 10): dynamic pricing pilot — Mike, Fri Sep 18; RD dynamic-pricing negotiations — Aaron, Sep 18; implementation — Mike, Oct 1; 2% pickup margin increase (5% → 7%) — Mike, by Oct 1; Indianapolis service partner — Aaron/Alvin, Sep 25; Catanese — Aaron, ASAP; Columbus personnel plan — Alvin, TBD.",ents:["alvin","mike","aaron","matt","m-indy","catanese","m-columbus","rd"],src:"'SupplyNow Strategic Plan | Action Items,' Sep 10",tab:"Sweep Sep 9–11"},
 {id:"F40",kind:"decision",date:"2026-09-12",text:"WSC direction (Alvin, text, Sep 12): 'The status quo will not work for WSC, especially as it relates to the Restaurant Depot relationship.' Expedite cost reduction and revenue. Wind down Indianapolis within 60–90 days (subject to discussions with RDG). Implement dynamic pricing ASAP. Other changes to follow. Monday priorities not yet sent back to Alvin.",ents:["alvin","wsc","m-indy","rd","pricing-dash","mike"],src:"Alvin text, Sep 12, 10:34–10:36 AM",tab:"Sweep Sep 12–14"},
 // ===== CFH =====
 {id:"F45",kind:"moment",date:"2025-08-18",text:"CFH 90-Day Service Agreement dated Aug 18, 2025, signed Aaron 8/29/25 and CFH. $225/day per route (5 stops), Net 7, 14 days' notice. The 90-day term ran to about Nov 16, 2025 and no renewal or long-term agreement is on file.",ents:["cfh","c-cfh-90","aaron","jordan"],src:"Contracts folder: CFHSigned.pdf",tab:"Documents read"},
 {id:"F46",kind:"moment",date:"2025-12-10",text:"CFH Letter of Intent signed by Mike (12/10/25) and Jordan. Non-binding; no exclusivity; 'Only a mutually executed agreement will carry binding terms.' Executed copy confirmed in the Contracts folder Sep 8.",ents:["cfh","c-cfh-loi","mike","jordan"],src:"Contracts folder: CFH.pdf",tab:"Documents read"},
 {id:"F47",kind:"decision",date:"2026-08-23",text:"CFH billing moved to $47 per stop ($45 delivery fee + $2 software fee), live in Airtable as formulas since Aug 23, 2026. Historical rows now display $47 even though weeks before Aug 23 were invoiced at $45.",ents:["cfh","airtable","mike"],src:"Mike's 'CFH Billing Update' memo; Aaron to Alvin Sep 1",tab:"Vendor partners"},
 {id:"F48",kind:"number",date:"2026-09-08",text:"CFH receivable: Camille's tab confirms Apr 6 – May 29 weeks ($12,105), Dec 15–19, 2025 ($1,935) and Aug 17–21 ($1,269) unpaid — $15,813 flagged plus $4,653 current; aging $5,922 at 1–30 days, $18,360 at 91+. The eleven Apr–Jun Mercury receipts ($15,145) paid January–March invoices. Camille: 'This is an accurate report.'",ents:["cfh","camille","mercury"],src:"Camille's CFH tab, Sep 8",tab:"Balances & AP/AR"},
 {id:"F49",kind:"finding",date:"2026-09-10",text:"CFH economics: routes about 40 miles (Cleveland) and 80 miles (Akron); about seven driver-hours a day across two drivers. CFH is incremental utilization of a truck already paid for by SNAP or another route and only hurts if it forces a new asset. Vehicle-only target is about $50/day. Alvin: 'No need to put together analysis now. I get the opportunity.'",ents:["cfh","alvin","mike","m-akron","m-cleveland"],src:"Alvin ↔ Mike, Sep 10",tab:"Sweep Sep 9–11"},
 {id:"F50",kind:"open",date:"",text:"CFH needs a current signed service agreement with the NewCo as counterparty (rates, terms, term, assignment), using the Aug 2025 agreement as the base. The Aug 12, 2026 addendum (Mike only) references a service agreement that on paper expired Nov 2025.",ents:["cfh","c-cfh-add","newco","mike"],src:"Order of operations, step 4",tab:"Order of operations"},
 // ===== Greenlight / Coltrane =====
 {id:"F52",kind:"moment",date:"2025-12-11",text:"Greenlight LOI executed (DocuSign 2293E707), Aaron George and Matthew Vann: up to $20,000/month, majority tied to Cleveland Restaurant Management Group (16 locations). Still no service or commission agreement; Alvin: 'We will negotiate a contract between the NewCo and Greenlight Grocery.'",ents:["glg","c-glg-loi","aaron","matt","alvin","newco"],src:"Contracts folder: SupplyNow Letter of Intent GLG.docx.pdf",tab:"Vendor partners"},
 {id:"F53",kind:"moment",date:"2026-07-22",text:"PA Coltrane Partnership & Service Agreement DocuSigned Jul 22, 2026 (effective Jul 20) by Aaron George and Akash Kapoor. Supersedes all prior agreements. 3.75% to SupplyNow, Net 32 pass-through, §4 backlog about $99,342 to clear by Aug 15, §5 factoring condition, 90-day termination, 24-month non-compete naming Coltrane and Restaurant Depot, NO assignment clause.",ents:["coltrane","pa","c-pa-coltrane","aaron","akash"],src:"Contracts folder (DocuSign CF157B0E)",tab:"Documents read"},
 {id:"F54",kind:"finding",date:"2026-08-24",text:"PA's Aug 24 Coltrane claim does not line up with the agreement: §4 fixed the backlog at about $99,342 to be cleared by Aug 15; PA's Aug 24 statement shows Coltrane at $138,938.35 after a $40,000 payment that day. The $3,400 'interest' PA deducted Jul 20 and the $500 'fee' Jul 9 have no basis in any agreement.",ents:["pa","coltrane","c-pa-coltrane","waqas"],src:"PA statements Aug 11 and Aug 24 (Gmail 1a058c58c5b80575)",tab:"PA reconciliation"},
 {id:"F55",kind:"number",date:"2026-08-11",text:"Coltrane money: Coltrane paid SupplyNow $272,323.45 (Apr 20 – Aug 10); SupplyNow paid PA $223,707 on the Coltrane account through Aug 11 (including $99,432 on Jul 23 and $20,000 on Aug 11 direct from WSC). Total credited to PA across both accounts to date: $319,657.",ents:["coltrane","pa","wsc"],src:"PA receipt log Aug 11; PA statement Aug 24",tab:"PA reconciliation"},
 {id:"F56",kind:"open",date:"",text:"Three Coltrane balances are in circulation — $192,541 on Max's AP tab, $138,938.35 on PA's Aug 24 statement, about $99,342 in §4 of the Jul 22 agreement — and SupplyNow's aging carries a blank row. Whether Coltrane obtained its own factoring (§5, from Aug 15) is not on record. PA's written consent to assign the agreement is needed (no clause exists).",ents:["coltrane","pa","c-pa-coltrane","aging","budget","newco"],src:"PA reconciliation tab; Sales & P&L item 10",tab:"PA reconciliation"},
 {id:"F57",kind:"moment",date:"2026-08-14",text:"PA Transport signed its own broker-carrier agreement with Ryan Transportation Service Inc on Aug 14, 2026 — one day before the §5 financing-transition date. SupplyNow is not a party; its purpose in the Coltrane program is not documented.",ents:["pa","ryantrans","c-ryan","coltrane"],src:"Contracts folder: Ryan Transportation & PA TRANSPORT LLC Executed Contract 2026-08-14",tab:"Documents read"},
 // ===== PA Logistics / RD Michigan =====
 {id:"F60",kind:"finding",date:"2026-09-10",text:"The weekly aging prices PA on the wrong model: it accrues PA Depot Michigan at $2,232.50/week ($33,487.45 over 15 weeks) via the generic 75/25 commission rule, while Aaron's own Aug 31 note says the balance accrues at $6,250/week — a gap of about $4,017/week, $60,262 over the same fifteen weeks. The $33,487.45 was never a measure of what PA is owed.",ents:["pa","aging","andrew","aaron","m-michigan"],src:"Fleet A/P aging week ending Sep 6; Aaron to Akash Aug 31",tab:"Service partners"},
 {id:"F61",kind:"number",date:"2026-08-24",text:"PA's stated balance after Aug 24: Coltrane $138,938.35, Restaurant Depot $72,800.00, total $211,738.35 (RD past-due stated as $53,600 on Aug 31). Total PA has billed on the RD account Mar 11 – Aug 24: $128,750 = $55,950 paid + $72,800 owed, about 107 full-day equivalents at $1,200/$600 (≈4.5 days/week).",ents:["pa","rd","m-michigan","akash"],src:"PA statement Aug 24; Akash email Aug 31",tab:"PA reconciliation"},
 {id:"F62",kind:"moment",date:"2026-05-22",text:"Five SupplyNow-initiated payments to PA bounced for insufficient balance between Apr 27 and May 22 ($13,475, $24,350, $14,350, $10,000, $17,000) before smaller amounts went through. May 7 shows both an ACH and a wire of $13,650 — check for a duplicate credit or return.",ents:["pa","mercury"],src:"Mercury notices Apr 27 – May 22",tab:"Service partners"},
 {id:"F63",kind:"decision",date:"2026-08-31",text:"From Sep 9 PA/Andrew covers all three Michigan stores Mon–Tue only; Logivex takes Wed–Fri; reassess at month end. Aaron to Akash: this 'should reduce the accruing balance from $6,250 to $2,500 weekly.' Alvin's repayment plan to Ajay (Sep 8): $20,000 Sep 9, $15,000 Sep 16, $15,000 Sep 23, remaining aged RD balance Sep 30.",ents:["pa","logivex","andrew","aaron","alvin","ajay","m-michigan"],src:"Aaron to Akash Kapoor, Aug 31; Alvin to Ajay, Sep 8",tab:"Service partners"},
 {id:"F64",kind:"moment",date:"2026-09-08",text:"Handover: Camille no longer receives PA's statements of account or makes PA payments — 'Glen is the one handling the payments and invoices since.' $119,432 of the credited total came direct from WSC and never touched Mercury, so Glen is now the primary source for PA's payment history. Glen, Sep 10: route finance items directly to him, not through Camille.",ents:["glen","camille","pa","wsc","mike"],src:"Camille to Mike, Sep 8, 8:58 AM; Glen, Sep 10, 10:01 AM",tab:"Service partners"},
 {id:"F65",kind:"decision",date:"2026-09-08",text:"PA reconciliation plan (Mike to Alvin and Glen, Sep 8; Alvin: 'I like this plan'): Waqas brings itemized invoices and the day log; Camille brings the Mercury export and a re-run aging at day rates; Glen brings WSC's statements and payment list since Jul 23; Aaron brings any PA acceptance of the $1,200/$600 card. Then a 60-minute sit-down ending in one number per account, then hand PA the reconciliation for acknowledgment.",ents:["pa","mike","alvin","glen","camille","waqas","aaron"],src:"Material Contract Analysis thread, Sep 8",tab:"PA reconciliation"},
 {id:"F66",kind:"open",date:"2026-09-10",text:"Mike is evaluating ending the Michigan PA service agreement at $1,000 a day as unsustainable (about $3,600/month of the operating hole). 90-day termination under the Jul 22 agreement; Logivex already runs Wed–Fri.",ents:["pa","m-michigan","mike","logivex"],src:"Sep 10 ops touchpoint notes",tab:"Sweep Sep 12–14"},
 // ===== Sigma =====
 {id:"F70",kind:"moment",date:"2026-02-16",text:"Sigma Fleet Partnership Agreement: services commencing Feb 16, 2026, 12-month term; Aaron signed 2/10/26; Sigma's line blank on the Drive copy (Camille: may have been signed in print). Reefer Lease Addendum: $2,500 refundable deposit, $500 month 1, $3,500/month months 2–12. §10.6 assignable on merger or sale. Countersigned copy still not in the folder.",ents:["sigma","c-sigma","aaron","aj","camille"],src:"Drive: Sigma_Fleet_LLC_Fleet_Agreement_FINAL.docx",tab:"Service partners"},
 {id:"F71",kind:"number",date:"2026-08-28",text:"Sigma level-set (Mike, Aug 28): owed to AJ $10,767.78 (Feb 26 – Jun 14 underpayment audit) + $22,288.13 (Jun 15 – Aug 23) = $33,055.91; AJ owes vehicle + insurance Mar–Aug at $4,354/month = $26,124; net $6,931.91 owed to AJ. Go-forward accrual proposed at $2,009.54 per biweekly payout. Camille confirmed the Jun 1–14 payout of $4,707.11 was never sent (it had been marked paid 7/21).",ents:["sigma","aj","mike","camille","aaron"],src:"Sigma level-set thread (Gmail 1a04945b98997367)",tab:"Service partners"},
 {id:"F72",kind:"finding",date:"2026-09-14",text:"Aaron's Sep 9 revision (net to AJ $4,431.91 with the $2,500 deposit; $77.91 in SupplyNow's favor if September is applied) reviewed Sep 14: not factual as of Sep 9. The $2,500 is a refundable security deposit under the addendum, not a cost AJ owes, and September is a full month of cost against no September earnings. Position: AJ is owed $6,931.91 through Aug 23; September rides in the biweekly accrual. Whether the deposit was ever collected is not on record.",ents:["sigma","aj","aaron","mike","c-sigma"],src:"Ask register, Sep 14",tab:"Ask register"},
 {id:"F73",kind:"open",date:"2026-09-10",text:"AJ Curry, Sep 10: 'I still haven't received the $4707.11 payout due July 21st or any payments from you guys since July 6th. Let me know ASAP what the plan is.' Finance (Glen), same day: 'I am not sure where we landed on this.' No reply on record; Finance sign-off on the net still missing; the weekly auto-report still carries Sigma at $32,978.12 gross with every row Open.",ents:["sigma","aj","glen","aging","camille"],src:"Gmail 19fa9cca30408588",tab:"Sweep Sep 12–14"},
 {id:"F74",kind:"open",date:"2026-08-31",text:"Sigma insurance statements conflict: Camille's Aug 31 email says 'we are still the insurance holder for Sigma'; the Aug 31 meeting notes say 'Sigma remains on their own insurance and will need to add Jacques.' Both cannot be true for the same vehicle. §5.2 of the agreement says SupplyNow insures the refrigerated box truck.",ents:["sigma","camille","nico","c-sigma"],src:"Camille Aug 31; Aug 31 meeting notes",tab:"Service partners"},
 // ===== Logivex / D&D =====
 {id:"F76",kind:"open",date:"2026-09-09",text:"Logivex started RD Michigan Wed–Thu–Fri on Sep 9 with no agreement, rate sheet or COI. Estimated $10,833/month (assumes PA's $2,500/week). Mo has an option on Ryder 16' reefers at $2k/month plus $0.90/mile, possibly up to six. Ledger: $9,000 paid Jul 24 'through WSC funds.' Mike started uniform standards and cost pass-through with Mo on Sep 10.",ents:["logivex","mo","m-michigan","aaron","camille","mike"],src:"Aaron Aug 31; Service Partner intake form Sep 8",tab:"Service partners"},
 {id:"F77",kind:"moment",date:"2025-10-15",text:"D&D Fleet Partnership Agreement effective Oct 15, 2025 (DocuSign dates Dec 18/23, 2025), 12-month term to Oct 14, 2026: $35/stop dry van, 16' reefer $65/hr, 26' dry box $200/day. It is a service agreement with a rate card, not a vehicle lease. No written termination is in the folder; SupplyNow insures Pappas's reefer until it ends.",ents:["dd","c-dd","pappas"],src:"Contracts folder: SupplyNow X Dynamic Delivery Agmt Draft.docx.pdf",tab:"Documents read"},
 {id:"F78",kind:"decision",date:"2026-09-07",text:"Relationship with D&D / John Pappas ended per Mike (Sep 7); CFH routes run on SupplyNow drivers. Only open item is the $2,065 balance (aged 91+ days), approved by Alvin Sep 1. Still to do: written notice ending the Oct 2025 agreement, pay the $2,065, remove the reefer from SupplyNow's insurance.",ents:["dd","pappas","mike","alvin","camille","nico"],src:"Mike, Sep 7; Ask register",tab:"Service partners"},
 {id:"F79",kind:"moment",date:"2026-09-09",text:"The Pappas van conversation (Mike to Alvin, Sep 9, 11:31 PM): 'I have not guaranteed or committed to anything with him.' Aug 20 discussed a Ford Transit Connect; Aug 21 photos showed it needs a windshield; proposed monthly vehicle-only rental. Sep 3 Pappas changed the offer to van plus driver at $300/day ($6,000–$6,600/month) — does not fit; target is about $50/day vehicle-only (~$1,000/month). Plan: let the urgency drain out, then a final vehicle-only offer.",ents:["pappas","dd","mike","alvin","cfh"],src:"Gmail 1a0786bf5e95fc0f, Sep 9",tab:"Service partners"},
 // ===== Fleet ownership =====
 {id:"F80",kind:"number",date:"2026-09-10",text:"Lease and finance run-rate about $18,500/month: Quality Supply $10,000, Fleet One $6,270, Penske $797 (was ~$8,400), MH $1,275, LG Chester $1,390, Kirill $557. Max's independent 'vehicle rentals & leases' line is $22,375 — close enough to be mutually confirming.",ents:["qs","fleetone","penske","mh","lgc","kirill","max"],src:"Fleet ownership tab, block 1",tab:"Fleet ownership & leases"},
 {id:"F81",kind:"finding",date:"2026-09-10",text:"Four of the six lessors are invisible in the books: Fleet One, MH, Kirill and Quality Supply are not rows in the weekly aging and (per Glen, Sep 8) not in WSC's A/P — about $13,700/month of committed payments plus Quality Supply's $240,000 forward obligation. Adding them as manual rows is on the Ask register (owner: Mike).",ents:["fleetone","mh","kirill","qs","aging","glen","mike"],src:"Glen, Sep 8, 1:23 PM; Fleet ownership tab",tab:"Fleet ownership & leases"},
 {id:"F82",kind:"finding",date:"",text:"Five of the six lessors carry clauses that block transfer. Only Fleet One has no anti-assignment provision. Penske treats an asset sale as a prohibited transfer; the three lease-to-owns (MH, LG Chester, Kirill) bar assignment and bar liquidation until paid, and void on insolvency. Goodwill is not the mechanism — written consent is.",ents:["fleetone","penske","mh","lgc","kirill","newco","c-penske","c-mh","c-lgc","c-kirill"],src:"Contracts folder, read Sep 8",tab:"Fleet ownership & leases"},
 {id:"F83",kind:"finding",date:"2026-09-08",text:"Truck #1008's lease is not in SupplyNow's name: it is between Quality Supply LLC (Jeff Hopkins) and LG Chester LLC. SupplyNow pays $1,390/month (contract $1,357.54) on a contract it is not party to. If all 21 payments since Jan 2025 were made ($28,508), the balance is about $8,492; Camille says about $5,000. Title passes to Quality Supply LLC on payoff unless something else is signed.",ents:["t1008","lgc","qs","hopkins","gretchen","c-lgc","camille"],src:"Contracts folder: Vehicle Lease to Own 2024.pdf",tab:"Fleet ownership & leases"},
 {id:"F84",kind:"open",date:"2026-09-09",text:"Gretchen (LG Chester) exact payoff chased twice by Glen (Sep 8, Sep 9). Camille, Sep 9 3:29 PM: 'No updates yet. Aaron is still confirming the total remaining balance, and I have not been able to reach Gretchen yet.' Alvin said Sep 9 the NewCo will assume this van, then retracted six hours later: 'There are some discrepancies that need to be resolved.' Last unquantified partner balance; Aaron (owner) on PTO.",ents:["lgc","gretchen","t1008","glen","camille","aaron","alvin","newco"],src:"Material Contract Analysis thread, Sep 8–9",tab:"Fleet ownership & leases"},
 {id:"F85",kind:"number",date:"2026-09-09",text:"Kirill balance: $8,685.23 confirmed Sep 8; two pending payments cleared as a single $1,114.00 wire on Sep 9, 11:06 AM (two months at the $557 ledger rate) → $7,569.23. Ledger's $557/month = $457 minimum + $100 profit payment, consistent with a balance under $15,000.",ents:["kirill","t1001","c-kirill","camille","mercury"],src:"Camille Sep 8; Mercury notice Sep 9",tab:"Fleet ownership & leases"},
 {id:"F86",kind:"decision",date:"2026-09-09",text:"Alvin, Sep 9, 3:30 PM: 'The NewCo will not assume the van in Kirill's name. I suggest that SupplyNow Inc. return it to Kirill. If not feasible, I suggest that you salvage it.' Constraint: §9.2 bars liquidation until the balance is paid, so salvage is not available while $7,569.23 is outstanding; return-and-release forfeits what has been paid in. Decision on return-vs-salvage still needed.",ents:["kirill","t1001","alvin","newco","c-kirill","mike","aaron"],src:"Alvin, Sep 9",tab:"Fleet ownership & leases"},
 {id:"F87",kind:"moment",date:"2025-06-13",text:"MH Auto Lease-to-Own for #1007 signed Jun 13, 2025: value $50,900, $5,000 down, $1,275 × 36 from Jul 15, 2025. Paid to date $5,000 + 14 × $1,275 = $22,850; remaining 22 payments = $28,050. Exit on 30 days' written notice, no buyout, payments non-refundable. Aaron is personal guarantor (lessor must pursue SupplyNow Inc's assets first). Summit County venue.",ents:["mh","t1007","c-mh","aaron","myron"],src:"Contracts folder: MH Leasing.docx.pdf.pdf",tab:"Fleet ownership & leases"},
 {id:"F88",kind:"finding",date:"2026-09-10",text:"Quality Supply: Camille (Sep 8) reports 'the current agreement is $10,000 per month with 24 months remaining' ($240,000 forward) plus $45,000 of vehicle backlog through June and 'Jeff Loans' $22,500. None of it is in the Contracts folder, the aging (manual row reads $0), the vehicle-rental GL, or the budget — a missed month is not computed anywhere. The subledger's arrears grow $7,500 May→June, not $10,000. Sizing: $8,015 (five-truck Nov 2024 sheet) + $1,357.54 (#1008) ≈ $9,373/month, so '$10,000' reads as the consolidated Hopkins payment — an inference, not a document.",ents:["qs","hopkins","camille","aging","budget","t1002","t1003","t1004","t1005","t1006","t1008"],src:"Camille to Alvin Sep 8, 2:38 PM; Payable Subledger",tab:"Fleet ownership & leases"},
 {id:"F89",kind:"decision",date:"2026-09-09",text:"Mike's position on Quality Supply (Sep 9): he has no knowledge of any Quality Supply relationship, agreement or $10,000-a-month obligation. Until Aaron or Camille produces the paper, the $240,000 forward obligation is unverified and stays out of any schedule the NewCo assumes.",ents:["qs","mike","aaron","camille","newco"],src:"Sweep Sep 9–11, block 7",tab:"Sweep Sep 9–11"},
 {id:"F90",kind:"open",date:"2026-09-13",text:"Units #1002–#1006 (former Hopkins leases: NV2500 $1,500, 5500XD $2,050, 5500XD $2,055, Transit $1,205, Freightliner $1,205 per month in Nov 2024) are carried as 'Owned' with no bill of sale, title or payoff on file. Alvin's 'Van Titles' email (Sep 13): track down whether SupplyNow has title; if not, formulate a plan. #1001, #1007, #1008 titles sit with the lessors until payoff.",ents:["t1002","t1003","t1004","t1005","t1006","qs","hopkins","alvin","camille"],src:"Lease Economics sheet; 'Van Titles,' Sep 13",tab:"Ask register"},
 {id:"F91",kind:"finding",date:"2026-09-10",text:"Fleet One has never appeared in the Fleet A/P aging despite monthly ACH since Nov 2025: ten pulls between $4,996.43 and $9,707.14, $43,889 through July on the GL (28% of fleet spend, second to Penske). Two July pulls of $5,502.73 failed for insufficient funds, cleared by a $9,034.66 wire Aug 17. The AP tab carries $28,176 'immediate.'",ents:["fleetone","aging","mercury","budget"],src:"Mercury notices; Max's GL; AP & One-Time tab",tab:"Fleet ownership & leases"},
 {id:"F92",kind:"open",date:"2026-09-14",text:"Fleet One paper gap: the master full-service lease for #2001/#2002 is not in the folder; only two Hino 556596 rental contracts (Jan 8, Feb 18 — still 'Active') and a COI. Three units are on rent (two 26-ft, one cargo van) as a bridge to three production leases (two 16-ft quoted 12–15 weeks Jul 31; one 26-ft Hino papered Aug 4). Ryan call Sep 15, 10 AM: rental rate and statement, ETA per unit, return process, whether all three leases still fit the Indianapolis/Columbus plan.",ents:["fleetone","ryan","t2001","t2002","hino","c-fo-rentals","mike","alvin","glen","matt"],src:"Mike, Sep 8 and Sep 14; Ryan Shepherd emails",tab:"Fleet ownership & leases"},
 {id:"F93",kind:"moment",date:"2026-02-03",text:"Penske (Sarah Kledzik) sent a termination letter for account 696207 on Feb 3, 2026: 'Your account remains in default, and we are enforcing the termination.' Aaron disputed the invoice math Feb 4; Penske confirmed receipt of $9,097.50. Vehicles stayed in service until Penske pulled them Aug 4–6, 2026; Camille: 'The trucks will be returned within the day.'",ents:["penske","t2003","aaron","camille","c-penske"],src:"Gmail 19c25233ed59be8b, 19fccc789b5e5db9",tab:"Fleet ownership & leases"},
 {id:"F94",kind:"open",date:"",text:"Penske residual claim is unquantified: the VLSA (§14 anniversary-only termination with buyout; §17 no assignment including by asset sale) plus Schedule A values and a final statement for 696207 are not on file. Statement Jun 3 shows $190; AP tab $1,523; last payment $796.99 Sep 1. Whether it binds the NewCo or stays with SupplyNow Inc is a question for counsel.",ents:["penske","c-penske","camille","newco","supplynow"],src:"Fleet ownership tab; Not located",tab:"Not located"},
 // ===== Trucks =====
 {id:"F100",kind:"number",date:"2026-09-03",text:"#1003 turbo quote: Fleet One Medina work order 21084 (Matt Hutton, 9/3/26) — remove and replace turbo assembly, 9 hours, parts $4,305.04 + labor $900 ($100/hr); regen $100; shop supplies $50; subtotal $5,355.04; tax $361.46; total $5,716.50. Sent by Julie Barbeisch Sep 3, 3:59 PM. Takes cumulative #1003 spend from $6,200 to about $11,900.",ents:["t1003","fleetone","julie","c-fma"],src:"'1003 quote,' Sep 3",tab:"Trucks & disposition"},
 {id:"F101",kind:"decision",date:"2026-09-14",text:"#1003 turbo position (Mike, Sep 14): not authorizing $5,716.50 on codes P0045 + P2563 alone. Shop to produce diagnostics that condemn the assembly (actuator sweep, commanded vs actual VGT position, wiring load-test, sensor voltages), part numbers, and a re-quote at FMA parts pricing (−20%, about $860 off). The actuator is a separately serviced part on this turbo family (Isuzu 8-98072-593-0); a complete RHF55V with actuator lists aftermarket at about $570 vs $4,305 quoted. Title from Hopkins first either way.",ents:["t1003","fleetone","julie","ryan","mike","c-fma","alvin","glen","matt"],src:"Mike forward, Sep 14; 4 PM deep dive",tab:"Ask register"},
 {id:"F102",kind:"finding",date:"2026-09-08",text:"Donor turbo from #1007 for #1003 ruled out (Mike, Sep 8): #1007's turbo is bad as well (both run the 5.2L 4HK1). Logged as repair line 1007-10, which adds a turbo to #1007's open brakes, steering and electrical scope and strengthens the exit case.",ents:["t1007","t1003","mike"],src:"Repair Priority Board, row 1007-10",tab:"Trucks & disposition"},
 {id:"F103",kind:"finding",date:"2026-09-08",text:"#1007 condition: down about 450 days as of Aug 26; torn down on the lift at Fleet One Medina; engine serial numbers removed (parted/rebuilt truck) so Fleet One will not proceed; complete brake loss on the Cleveland–Medina drive (overhaul $2,200–$6,000); steering, electrical back-feed, rear-door work open; turbo bad. MH not returning calls. Fleet One wants the truck out of the shop.",ents:["t1007","fleetone","mh","myron"],src:"Mike Aug 26; Repair Priority Board Sep 2",tab:"Trucks & disposition"},
 {id:"F104",kind:"decision",date:"2026-09-08",text:"Recommendation: release #1007 first, on MH's 30-day clause — the only unit where walking away stops cash going out ($1,275/month, $28,050 remaining) at no exit cost, after a year of producing no capacity. Sequence: Aaron's sign-off as guarantor → Ryan at Fleet One to void the FM/RM contract and invoice work to date → written notice to MH by email and certified mail → pay Sep 15 on time → MH's written release on pickup → off the NICO schedule, plate returned, Decommissioned in Airtable. Reverses the Sep 2 repair-board 'don't walk' call.",ents:["t1007","mh","fleetone","ryan","aaron","mike","c-mh","c-fma","nico","airtable"],src:"Trucks & disposition tab",tab:"Trucks & disposition"},
 {id:"F105",kind:"moment",date:"2026-09-02",text:"#1002's rooftop reefer is not repairable per Thermo King Hilliard (Sep 2); damage traced to the Jul 29, 2025 incident; replacement quote pending from Brad. Exhaust torn off (right bank) and holed (left). Drivable dry; sitting at Thermo King, $0 diag, ready for pickup. Columbus refrigerated delivery down since about Aug 24; RD switched Columbus delivery off at its end.",ents:["t1002","thermoking","m-columbus","rd"],src:"Thermo King Hilliard Sep 2; RD storefront Sep 9",tab:"Trucks & disposition"},
 {id:"F106",kind:"open",date:"2026-09-09",text:"Columbus reefer coverage: Ed and Mel recommend moving the working reefer to Columbus and turning off Indianapolis delivery (Columbus leads on sales; Dakota logged 100+ more hours). Fleet One has no 16/20-ft reefers, offered a 26-footer; unsure Dakota can drive one; Ryder or another 26-footer under consideration. No decision on record. Ties to the Indianapolis wind-down.",ents:["m-columbus","m-indy","ed","mel","fleetone","t1002","mike","aaron"],src:"'Truck/Van situation in Columbus,' 'trucks,' Sep 8–9",tab:"Sweep Sep 9–11"},
 {id:"F107",kind:"open",date:"2026-09-10",text:"WSC owns a 2019 Chevy Express 2500 'in good shape, especially for around town drives' and offered it to SupplyNow (Alvin, Sep 10, 8:02 AM and 12:10 PM); it would need shipping. Not answered on record.",ents:["wsc","alvin","mike","cfh"],src:"'Chevy Express 2500,' Sep 10",tab:"Ask register"},
 {id:"F108",kind:"finding",date:"2026-09-12",text:"Cost side of the deficit beyond pricing: Indianapolis (losing over $10,000/month), the three dead leases (#1001, #1003, #1007 at about $4,300/month), and the Michigan day-rate structure (about $3,600/month). The network ran about −$39,649/month on the Aug 25 model; Max's budget carries EBITDA of ($24,208) to ($40,708)/month.",ents:["m-indy","t1001","t1003","t1007","m-michigan","budget","pricing-dash"],src:"Pricing go-live tab, block 2",tab:"Pricing go-live & labor budget"},
 // ===== Balances & AP/AR =====
 {id:"F110",kind:"moment",date:"2026-09-07",text:"Mike to Camille, Sep 7, 8:59 AM ('AP/AR check-off'): 'the numbers in our own systems don't tie out to what's been paid… are these the actual amounts, or are they stale because the check-offs never happened?' Asks for paid / submitted / disputed marks on Sigma, PA, SNAP and CFH verified to Mercury, plus lease payoffs and folder access. Fourth such request since Jun 1 (Jun 1, Jul 8, Aug 28, Sep 7).",ents:["mike","camille","aging","sigma","pa","snap","cfh"],src:"Gmail 1a07bca510d2cb92",tab:"Balances & AP/AR"},
 {id:"F111",kind:"decision",date:"2026-09-08",text:"Camille, Sep 8, 2:40 PM: 'I will make sure to update those tracking fields in the Weekly Vendor Aging sheet and Airtable moving forward so the records stay current.' Paid / submitted / disputed to be marked at the moment of payment. First report on the new basis is the Monday after Sep 8. Sigma tally and SNAP marks corrected; CFH flags stand; PA moved to Glen.",ents:["camille","aging","airtable","mike"],src:"AP/AR check-off thread, Sep 8",tab:"Balances & AP/AR"},
 {id:"F112",kind:"number",date:"2026-09-10",text:"Balances snapshot (Sep 10): PA RD Michigan $33,487.45 ours vs $72,800 theirs; PA Coltrane blank vs $138,938.35; Sigma $6,931.91 net; D&D $2,065; CFH receivable $15,813 past due + $4,653 current; SNAP receivable $30,286.88; MH $28,050; LG Chester ≈$5,000 (math says ≈$8,492); Kirill $7,569.23; Quality Supply $45,000 backlog + $240,000 forward; Fleet One $28,176; Penske $190 (statement) / $1,523 (AP tab); Logivex $0. The aging total across vendors it carries is $68,530.57, while PA alone claims $211,738.35.",ents:["pa","sigma","dd","cfh","snap","mh","lgc","kirill","qs","fleetone","penske","logivex","aging"],src:"Balances snapshot tab",tab:"Balances & AP/AR"},
 {id:"F113",kind:"open",date:"2026-09-01",text:"Small open items from Alvin's Sep 1 'Payment Requests': Damonte's $400 advance repayment (Camille to confirm receipt); HFLA interest-free loan final auto-pull failed Sep 1, retry and obtain a $0 payoff letter; office move-out (lease ended, six months in arrears, '90% done'); Extra Space Storage $75/month.",ents:["alvin","camille","glen","aaron"],src:"Gmail 1a05d261ece02d6a",tab:"Ask register"},
 {id:"F114",kind:"number",date:"2026-09-10",text:"West 25th Meats owes SupplyNow $1,056 (Quote SN-20260821-CIN04), now paying by check. Not on any aging. Uniform spend $700 approved by Glen; $522.72 order placed with Cleveland Printwear (24 Sport-Tek tees, COD, due Sep 18).",ents:["w25","glen","mike"],src:"'Uniform & Hoodie Funding,' Sep 10",tab:"Sweep Sep 9–11"},
 // ===== Budget / P&L =====
 {id:"F120",kind:"number",date:"2026-09-08",text:"Max's Stabilization Budget (Sep 2026 – Aug 2027, per month): RD $145,800, SNAP $40,000, Other $5,000, Coltrane $0 → revenue $190,800; driver payroll $48,400; jobber $66,400; fleet $22,300; gas/repairs/insurance $10,000/$4,000/$14,700; gross profit $25,000; opex $65,708 Sep, $52,708 Oct, $49,208 after; EBITDA ($40,708) Sep, ($27,708) Oct, ($24,208) after. Status Quo scenario: EBITDA ($72,737).",ents:["budget","max","alvin","rd","snap","coltrane"],src:"SupplyNow Operating Budget 9.7.26, Budget and Scenario Comparison tabs",tab:"Sales & P&L"},
 {id:"F121",kind:"finding",date:"2026-09-08",text:"Budget items verified: RD revenue Jan–Jul matches Camille's receipts and QuickBooks to the dollar (Jan $68,530 … Jul $99,987); Coltrane revenue matches for Feb, Mar, Apr, Jun (May and Jul differ); driver payroll and vehicle insurance within a few hundred dollars; fleet spend by vendor ties to the leases (Penske $79,913 = 51% of Jan–Jul fleet cost).",ents:["budget","max","camille","rd","coltrane","penske"],src:"Sales & P&L tab, block 2",tab:"Sales & P&L"},
 {id:"F122",kind:"open",date:"2026-09-08",text:"Budget items open for Max/Glen: (1) Coltrane cost is buried in 'Jobber costs — non-Coltrane' (QB books Coltrane Fleet Partner Costs separately, Jun $101,450); (2) the budget removes Coltrane revenue but only $54K of its cost; (3) the $112,962 July RD base is 13% above every booked July figure ($99,987) — applying the uplift to $99,987 gives $129,000, not $145,800; (4) September carries the full uplift against the tab's own 50% note; (6) SNAP $40,000 flat is optimistic by $6K–$10K; (7) fleet $22,300 assumes rentals returned; (9) rent $1,500 continues though the lease ended; (11) Jumpstart; (14) Claros terms; (15) #ERROR! cells.",ents:["budget","max","glen","coltrane","rd","snap","jumpstart","claros","fleetone"],src:"Sales & P&L tab, block 3",tab:"Sales & P&L"},
 {id:"F123",kind:"finding",date:"2026-09-08",text:"Two versions of June in QuickBooks: the earlier overview shows June revenue $200,395 / NOI ($66,969); the updated one $253,174 / +$42,643. The $52,779 swing is RD ($71,217 → $106,028) and Coltrane. July one-timers ($50,000 Jumpstart, $17,000 reimbursements, $14,500 software contractors, $10,000 legal, $7,014 taxes) put July NOI at roughly ($119,000) on the QB basis vs Max's ($33,957) EBITDA.",ents:["budget","max","jumpstart","rd","coltrane"],src:"Aaron's 'Sales' workbook; Sales & P&L items 12–13",tab:"Sales & P&L"},
 // ===== Labor / payroll =====
 {id:"F125",kind:"number",date:"2026-09-14",text:"Weekly hourly budget live Sep 14: Sep 14–27 budget is 14 drivers, 974 hours (948 regular + 26 OT), $21,569 gross — Cleveland 500 (Valley View 170), Wilkes-Barre 230, Pittsburgh 124, Columbus 70, Indianapolis 50. Last period (Aug 31 – Sep 11): 819.7 hours, $17,895, no OT, 83% of budget, 34 open punch flags; Indianapolis the only location over (113%).",ents:["hourly-budget","mike","mel","ed","m-cleveland","m-wb","m-pittsburgh","m-columbus","m-indy"],src:"Google Sheet 1RItdiYR8O0D90fx4BjxAITGzp6h2PLcj6tV9Ja89uK8",tab:"Pricing go-live & labor budget"},
 {id:"F126",kind:"decision",date:"2026-09-10",text:"Labor decisions (Sep 10 ops touchpoint): Columbus hire authorized to replace overtime with straight time; Marcelys Jones to 30 hours a week from the next period; Christine Puskar off the Monday Depot/Cleveland rotation; Marcel to cross-train on Canton and CFH routes; Pete confirmed for holiday pay. Estimated savings $1,500–$2,500/month — do not book more until two full periods are in.",ents:["hourly-budget","mike","mel","ed","m-columbus"],src:"Gemini notes, Sep 10",tab:"Sweep Sep 12–14"},
 {id:"F127",kind:"open",date:"2026-09-15",text:"Open before the Sep 15 Justworks intake: pull the Deel census (every W-2 and 1099) and stage Articles of Incorporation, EIN, entity documents; decide which entity signs (SupplyNow Inc vs NewCo — 'Decision needed'); Justworks' written answers on tier/price, exclusions, workers' comp for delivery drivers, multi-state; what the Nov 6 window requires by when; Deel exit terms (not yet asked).",ents:["justworks","deel","glen","mike","mel","camille","alvin","newco","supplynow"],src:"Payroll / PEO tab, block 4",tab:"Payroll / PEO"},
 {id:"F128",kind:"open",date:"2026-09-12",text:"Alvin's 'Salaries' email (Sep 12, cc Glen): confirm Ed's and Mel's current salaries (Alvin believes Ed $70,000; Mel $50,000 or $55,000; is Mel full-time) plus any pay context going forward. Alvin offered a live call Monday. Open.",ents:["alvin","glen","ed","mel","mike"],src:"Gmail 1a0964d0d3a8e478",tab:"Sweep Sep 12–14"},
 {id:"F129",kind:"moment",date:"2026-09-11",text:"Sep 11 payments turbulence: a PayPal outage 'just added fuel to the fire' (Aaron); Alvin sent Glen and Max 'a workaround until we get our new payroll provider set up' and stressed communicating to the team. Wage-issue process improvements were raised Sep 5 ('Claros Support | Wage Issues'); Mike: 'Anything tied to pay needs a fast, clean path.'",ents:["aaron","alvin","glen","max","claros","justworks"],src:"Texts Sep 11; Gmail 1a072eb4115d8610",tab:"Sweep Sep 12–14"},
 // ===== Authority / licensing / insurance =====
 {id:"F130",kind:"decision",date:"2026-09-10",text:"Alvin, Sep 10, 8:30 PM: 'I am adding Glen Surnamer who will work with you on the go-forward plan. As a note, we might need to sub-contract through SupplyNow Inc. until we stand up licensed under the NewCo.' Timing of the NewCo MC filing is a decision needed; Glen and Mike met Sep 11. PUCO (Ohio intrastate) registration to be reinstated (Alvin → Camille, Sep 12).",ents:["alvin","glen","mike","newco","supplynow","camille"],src:"'Drivers' thread Sep 10; 'PUCO Registration' Sep 12",tab:"Ask register"},
 {id:"F131",kind:"open",date:"2026-09-10",text:"Authority filings to verify: BOC-3, biennial MCS-150, annual UCR; IFTA/IRP for any unit over 26,000 lb GVW; FDA sanitary-transport compliance and whether any site trips an Ohio ODA wholesale-food license; Ohio CAT and vendor's license with the accountant. A 'Licensing & Authority' folder was started with the CP-575 and Certificate of Incorporation.",ents:["supplynow","mike","camille","contracts-folder"],src:"Mike, Sep 10, 8:26 PM",tab:"Sweep Sep 9–11"},
 {id:"F132",kind:"open",date:"2026-09-10",text:"Insurance amendment: add Carmelo Alvarez Rivera, Marcelys Jones and Christine Puskar; do not add Andrew Gist (PA service partner with own coverage). Requests submitted; Alvin, Sep 10: 'Please do not follow up with Howden for now though.' Alvin ran background checks on nine drivers and wants to discuss 'a couple of observations' — meeting not yet held.",ents:["nico","alvin","camille","andrew","ed","mike"],src:"'Drivers' and 'Driver changes,' Sep 9–10",tab:"Ask register"},
 {id:"F133",kind:"number",date:"2026-06-05",text:"Auto liability policy: National Indemnity Company via RT Specialty / Howden, term 6/5/2026 – 6/5/2027, estimated premium $175,874 in SupplyNow Inc's name. Ledger: IPFS monthly installments $15,921 (Jul 23) and $15,162 (Aug 5). Certificates issued to Restaurant Depot, SNAP, Fleet One units, Sigma's reefer. Max's budget carries $14,700/month — understated about $1,200/month if IPFS is the cash figure.",ents:["nico","supplynow","rd","snap","fleetone","sigma","budget"],src:"Gmail 1a05d261ece02d6a; quote #026876998B",tab:"Other obligations"},
 // ===== Other obligations =====
 {id:"F135",kind:"number",date:"2026-09-07",text:"Verizon Connect: 14 vehicles, list $1,110.76/month ($965.02 with promo), 36-month commitment from Aug 27, 2025, installs Oct 24 – Nov 4, 2025. Cancelled per Mike (Sep 7) with a remaining balance owed by SupplyNow Inc / Aaron as signer — roughly $6,000–$6,550 across 14 units on the order form's schedule. Actual figure and cancellation notice not on file. Telematics now via Fleet One's Samsara (access granted Aug 26).",ents:["verizon","c-verizon","supplynow","aaron","rapkin","fleetone"],src:"Drive 1oNIS17MNkYXro9PkU2M47j4E48mD2ii4",tab:"Other obligations"},
 {id:"F136",kind:"finding",date:"2026-09-14",text:"AIT / custom software inspected Sep 14: 21,409 orders (11,884 paid, $1,000,998.91), newest dated Apr 20–21, 2026; last reconciled week Dec 27 – Jan 2; 2,459 user accounts; Aaron's last activity Oct 9, 2025. No dependency in Mike's stack (28 project folders, every scheduled task searched). Exposure: Django DEBUG on in production; Swagger public. Credentials (Railway, Vercel, Twilio, Stripe, S3) sit with Aaron and AIT; Mike's GitHub org invite unaccepted (wants outside-collaborator read instead).",ents:["portal","ait","aaron","mike","alvin","glen"],src:"admin.supplynow.org, api.supplynow.io, gh api, Sep 14",tab:"Sweep Sep 12–14"},
 {id:"F137",kind:"decision",date:"2026-09-14",text:"AIT position (draft reply to Alvin, Sep 14): no Period 4 payment; hold Period 3 (Sep–Nov, $9,000–$10,000) pending the contract and a Mar–Aug ticket history; export the data this week; fix the debug exposure; add repo read access, Railway/Vercel ownership, Twilio/Stripe/S3 keys and an AIT IP assignment to the NewCo P0 transfer list; then park or shut down and stop the retainer. Caveat: view from outside; Aaron (back Sep 21) is the only source on how it was built.",ents:["ait","portal","alvin","aaron","mike","newco"],src:"Sweep Sep 12–14, block 6",tab:"Sweep Sep 12–14"},
 {id:"F138",kind:"open",date:"2026-09-13",text:"Alvin's 'AIT Software' email (Sep 13, cc Glen): 'We are paying them $10,000 quarterly, and Aaron said the importance to the organization is 9/10. That said, he has been very vague about the arrangement.' Aaron's Sep 1 figure was $9,000/quarter; the ledger shows $9,500 on Jul 27 (WSC funds). Contract is physical, in storage; Alvin chased Camille again Sep 13.",ents:["ait","alvin","aaron","camille","glen"],src:"Gmail 1a09b6060752d8e0",tab:"Sweep Sep 12–14"},
 {id:"F139",kind:"open",date:"",text:"Rapkin settlement: whether a final agreement was executed, and whether any Innovation Foods payments have arrived, is not in mike@ email, Drive or the Contracts folder. By the proposal's own terms every restriction and the 3.5% stream terminate if SupplyNow 'sells or transfers ownership, changes corporate identity, or otherwise dissolves,' so nothing carries to the NewCo.",ents:["rapkin","c-rapkin","innovation","newco","supplynow"],src:"Gmail 19cfdc6ea13593a6",tab:"Not located"},
 {id:"F140",kind:"open",date:"",text:"Still not located after reading the Contracts folder (Sep 8): RD 2026 countersignature; Sigma countersigned copy; any Coltrane customer-side agreement and §5 factoring confirmation; PA itemized invoices and day log; Fleet One master lease and rental agreements for the three units on rent; Penske Schedule A and final statement; bills of sale/titles for #1002–#1006; LG Chester and Kirill payoffs; D&D termination notice; any CFH agreement after Nov 2025; Rapkin final agreement; Verizon final balance.",ents:["contracts-folder","rd","sigma","coltrane","pa","fleetone","penske","qs","lgc","kirill","dd","cfh","rapkin","verizon"],src:"Not located tab",tab:"Not located"},
 // ===== Order of operations =====
 {id:"F145",kind:"decision",date:"2026-09-08",text:"Order of operations: Phase 0 truth and stop-loss (AP/AR check-offs, PA tie-out, #1003 turbo, #1007 notice, lease payoffs — Sep 11) → Phase 1 consents that gate transfer (NewCo USDOT/MC, PUCO, JRD countersign and transfer approval, PA consent to assign, Quality Supply → SupplyNow/NewCo on #1008, Kirill and MH assignment or exit — Sep 18) → Phase 2 re-paper (SNAP Schedule 1, CFH, Greenlight, Sigma countersign, D&D termination, Logivex note — Sep 25) → Phase 3 close out SupplyNow Inc obligations (Penske, Verizon, Rapkin, HFLA, office, Hino rentals — Sep 25) → Phase 4 purchase-agreement schedule (Oct 2).",ents:["newco","supplynow","alvin","glen","mike","aaron","camille","rd","pa","snap","cfh","glg","sigma","dd","logivex","penske","verizon","rapkin","qs","kirill","mh"],src:"Order of operations tab",tab:"Order of operations"},
 {id:"F146",kind:"open",date:"2026-09-07",text:"Awaiting Alvin: he said Sep 7 he would 'circle back throughout the week' on the ledger items to create a plan of action, and that 'updates negotiated behind the scenes' should be shared symmetrically. Not yet shared; affects the PA repayment plan and any counterparty talks.",ents:["alvin","mike","pa"],src:"Material Contract Analysis thread, Sep 7, 12:26 PM",tab:"Ask register"},
 {id:"F147",kind:"open",date:"2026-09-12",text:"Aaron on vacation Sep 14–18 and declined the Sep 16 catch-up and Sep 17 team meeting. He owns the RD negotiation (Sep 18), Catanese, the Indianapolis partner search (Sep 25), the AIT contract, the Gretchen balance and the RD importer template — each of those dates needs a stand-in or a slip.",ents:["aaron","alvin","rd","catanese","m-indy","ait","lgc","pricing-dash"],src:"Login & Platform Audit thread, Sep 12",tab:"Ask register"},
 {id:"F148",kind:"moment",date:"2026-09-01",text:"Alvin's 'Fleet Costs' email (Sep 1, 9:14 AM): 'a list of all of our fleet partners (current and former) and how much we owe each,' plus estimated monthly spend. 'WSC will not provide any more approvals until this information is provided.' Answered Sep 10: eleven relationships, not six; two of the six names are one party; 'Reserve Fleet' is not a counterparty. Alvin separately asked Mike to 'quietly insert yourself into this workstream… We keep dealing with surprises.'",ents:["alvin","aaron","mike","wsc","max","camille"],src:"'Fleet Costs,' Sep 1",tab:"Ask register"},
 {id:"F149",kind:"number",date:"2026-09-10",text:"Operator run-rate about $31,200/month after the Sep 9 split: PA $10,833 ($2,500/week), Logivex about the same (unrated), Sigma $9,527 (15-week actual average, $2,198.54/week). Max's independent jobber figure excluding Coltrane is about $45,000, which also carries the Coltrane pass-through. Two of the four operators run without current paper (Logivex, PA's RD card).",ents:["pa","logivex","sigma","max","m-michigan"],src:"Service partners tab, block 1",tab:"Service partners"},
 {id:"F150",kind:"moment",date:"2026-09-11",text:"Mike sent the 35-platform Login & Platform Audit on Sep 11 (findings artifact 04fc3a18). Alvin: 'Glen and I walked through a plan of action… He will connect with you to sort through everything.' Alvin also asks of the custom software: what does it do, and is it essential.",ents:["mike","alvin","glen","portal","ait"],src:"Gmail 1a09125bb3b95b7e",tab:"Sweep Sep 12–14"},
 {id:"F151",kind:"number",date:"2026-09-10",text:"Fleet One FMA terms (Mike's Aug 5 memo): $219/unit/month for 1003 and 1007; 3 PM services + 1 DOT inspection a year; labor $105/hr; parts fleet pricing −20%; outside repairs −10%; tires −10%; nights/weekends $157.50/hr; +10% shop supplies. Aaron 'Signed and Returned' Aug 26. Fleet One granted Mike a Samsara account and API token Aug 26.",ents:["fleetone","c-fma","t1003","t1007","aaron","mike"],src:"Mike Aug 5; Ryan Shepherd Aug 25–26",tab:"Fleet ownership & leases"},
 {id:"F152",kind:"finding",date:"2026-09-09",text:"Per-depot cost is not on record, so 'profitability by store' is a target, not a measured result. Cost to serve is per stop, not per dollar (Akron's average pickup basket is $1,087; Wilkes-Barre's $732), which is why fee levers matter more than rate levers on small-basket depots. No elasticity in the model — every card reprices historical volume with nobody churning.",ents:["rd","pricing-dash","m-akron","m-wb","m-michigan"],src:"RD pricing tiers tab, block 6",tab:"RD pricing tiers"},
 {id:"F153",kind:"finding",date:"2026-09-10",text:"Levers per week across all nine RD stores: +1 point delivery markup $1,271; +$10 delivery fee $1,171; +$10 pickup fee (does not exist today) $1,104 — 994 pickup orders in 9 weeks pay $0 in fees; +1 point pickup markup $975 (least visible; no competing free alternative).",ents:["rd","pricing-dash"],src:"RD pricing tiers tab, block 3",tab:"RD pricing tiers"},
 {id:"F154",kind:"moment",date:"2026-09-09",text:"Alvin asked Camille for vehicle details on the Kirill, Gretchen and John Pappas vans (year, make, model, markets, clients, location, mileage, status, last driven) Sep 8–9. Camille sent a Vehicle Details sheet Sep 9 (Drive 1DBkeYWVTP2A_yEfvOqeNqzo23JVpOOyK8Wj1SJi5r4E).",ents:["alvin","camille","t1001","t1008","pappas"],src:"Sep 8, 9:43 PM and Sep 9, 9:54 PM",tab:"Ask register"},
 {id:"F155",kind:"number",date:"2026-09-11",text:"RD backfill: nine reconciled orders from the last 14 days ($8,231.84) have no store/cost center as of Sep 11 and need assigning before partner payout. Employee Records base gained an 'Insurance Coverage Responsibility' column Sep 11.",ents:["rd","airtable","sigma","mike"],src:"Sweep Sep 12–14, block 5",tab:"Sweep Sep 12–14"}
];
